import java.time.Duration;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
public final class Lookup {
  private final Loader loader;
  public Lookup(Loader loader) { this.loader = loader; }
  public CompletableFuture<String> find(String key, Duration remaining) {
    LoadHandle handle = loader.acquire(key);
    return handle.result.orTimeout(remaining.toNanos(), TimeUnit.NANOSECONDS);
  }
}

files.Loader.java:
public interface Loader {
  LoadHandle acquire(String key);
}

