import java.util.concurrent.CompletableFuture;
public final class LoadHandle {
  public final CompletableFuture<String> result;
  private final Runnable cancellation;
  public LoadHandle(CompletableFuture<String> result, Runnable cancellation) {
    this.result = result; this.cancellation = cancellation;
  }
  public void requestCancellation() { cancellation.run(); }
}

